// <auto-generated/>
namespace Fanex.Age.UI
{
    using System.IO;
    using System.Text;
    using System.Web.UI;
    using TplCore.Element;

    /// <summary>
    /// Filter:
    ///     1. Remove end html tag 
    /// </summary>
    public class TplHtmlTextWriter : HtmlTextWriter
    {
        public const string END_HTML_TAG = "</html>";

        public TplHtmlTextWriter(TextWriter writer)
            : base(writer)
        { }

        public TplHtmlTextWriter(TextWriter writer, string tabString)
            : base(writer, tabString)
        { }

        public override void Write(object value)
        {
            // Remove end html tag at the end to fix bug xml is not welformed in Opera browser
            Template template = value as Template;

            if (template != null)
            {
                StringBuilder content = new StringBuilder(4096); // 4KB
                template.ToString(ref content);
                content.Remove(content.Length - END_HTML_TAG.Length, END_HTML_TAG.Length);
                base.Write(content);
            }
            else
            {
                base.Write(value);
            }
        }

        public bool RemovedEndHtmlTag = false;

        public override void Write(string s)
        {
            int index = s.Length - END_HTML_TAG.Length;
            RemovedEndHtmlTag = false;
            if (index >= 100)
            {
                string end_html_tag = s.Substring(index);
                if (string.Compare(end_html_tag, END_HTML_TAG, true) == 0)
                {
                    s = s.Remove(index);
                    RemovedEndHtmlTag = true;
                }
            }

            base.Write(s);
        }
    }
}
